using System;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace Ara {
 public static class PlanEditTests {
  static void Assert(bool yes,string message){if(!yes)throw new Exception(message);}
  static void With(string dir,string name,Action<MainForm> action){var s=State.New();var d=s.GetDay(DateTime.Today);d.Wake=DateTime.Today.AddHours(8);GridEngine.Ensure(s,d);using(var f=new MainForm(new Store(Path.Combine(dir,"edit-plan-"+name+".json")),s,true)){f.Show();Application.DoEvents();try{action(f);}finally{f.Quit();}}}
  static PhoneCommand Cmd(MainForm f,string op,int start,int count=1,int lane=0){return new PhoneCommand{op=op,lane=lane,first=start,last=start+count-1,date=f.Day.Date,baseRevision=f.PhoneSnapshot(f.Day.Date).revision,requestId=Guid.NewGuid().ToString("N")};}
  static PhoneBlock Meal(PhoneDay day,string id){return day.planned.Single(x=>x.mealId==id);}
  static PhoneDay EatSecond(MainForm f){var second=Meal(f.PhoneSnapshot(f.Day.Date),"b6");var c=Cmd(f,"copy",second.start+6,3,1);c.sourceId=second.id;f.PhoneApply(c);var score=Cmd(f,"score",second.start+6,3,1);score.score=7;return f.PhoneApply(score);}
  static PhoneDay MovePlan(MainForm f,PhoneBlock source,int start){var c=Cmd(f,"move",start);c.id=source.id;return f.PhoneApply(c);}
  static void Same(PhoneBlock a,PhoneBlock b){Assert(a.id==b.id&&a.start==b.start&&a.count==b.count&&a.name==b.name&&a.category==b.category,"unrelated planned block changed");}
  public static void Run(Action<string,Action> check,string dir){
   check("plan edit: PC drag moves a recorded upper meal and prep without changing actuals or future",()=>With(dir,"pc",f=>{var before=EatSecond(f);var second=Meal(before,"b6");string records=PhoneCodec.Hash(PhoneCodec.Json(f.Day.Records));f.Board.SimulateDrag(0,second.start,second.start+3,false);var after=f.PhoneSnapshot(f.Day.Date);Assert(Meal(after,"b6").start==second.start+3,"PC upper drag accepted");Assert(after.planned.Single(x=>x.name=="2끼니 준비").start==second.start+2,"prep follows meal");Assert(PhoneCodec.Hash(PhoneCodec.Json(f.Day.Records))==records,"actual times and scores unchanged");foreach(var b in before.planned.Where(x=>x.id!=second.id&&x.name!="2끼니 준비"))Same(b,after.planned.Single(x=>x.id==b.id));}));
   check("plan edit: phone upper drag persists and later actual edits keep the manually moved plan",()=>With(dir,"phone",f=>{var before=EatSecond(f);var second=Meal(before,"b6");var moved=MovePlan(f,second,second.start+3);var actual=moved.actual.Single(x=>x.mealId=="b6");var c=Cmd(f,"move",actual.start+1,1,1);c.id=actual.id;var after=f.PhoneApply(c);Same(Meal(moved,"b6"),Meal(after,"b6"));Assert(after.actual.Single().start==actual.start+1,"actual moved separately");var loaded=PhoneCodec.Snapshot(f.Store.Load(),f.Day.Date);Assert(loaded.revision==after.revision,"manual upper move survives restart");}));
   check("plan edit: upper preparation drag moves its meal as one group",()=>With(dir,"prep",f=>{var before=f.PhoneSnapshot(f.Day.Date);var prep=before.planned.Single(x=>x.name=="2끼니 준비");var after=MovePlan(f,prep,prep.start+3);Assert(after.planned.Single(x=>x.id==prep.id).start==prep.start+3&&Meal(after,"b6").start==Meal(before,"b6").start+3,"prep and meal moved together");Assert(after.actual.Count==0,"no actual entry added");}));
   check("plan edit: recorded workout upper block remains editable",()=>With(dir,"workout",f=>{var before=f.PhoneSnapshot(f.Day.Date);var zone=before.planned.Single(x=>x.category=="존2");var c=Cmd(f,"copy",zone.start,zone.count,1);c.sourceId=zone.id;f.PhoneApply(c);var recorded=f.PhoneSnapshot(f.Day.Date);var after=MovePlan(f,zone,zone.start-5);Assert(after.planned.Single(x=>x.id==zone.id).start==zone.start-5,"upper workout moved");Same(recorded.actual.Single(),after.actual.Single());}));
   check("plan edit: editing upper current meal details does not edit the actual record",()=>With(dir,"detail",f=>{var before=EatSecond(f);var second=Meal(before,"b6");var c=Cmd(f,"detail",second.start,second.count);c.name="2끼니 계획 수정";c.category="식사";c.mealId="b6";var after=f.PhoneApply(c);Assert(Meal(after,"b6").name==c.name,"planned details changed");Same(before.actual.Single(),after.actual.Single());foreach(var b in before.planned.Where(x=>x.id!=second.id))Same(b,after.planned.Single(x=>x.id==b.id));}));
   check("plan edit: a collision involving meal prep rejects the whole move without data loss",()=>With(dir,"collision",f=>{var before=EatSecond(f);bool rejected=false;try{MovePlan(f,Meal(before,"b6"),68);}catch(InvalidOperationException){rejected=true;}Assert(rejected,"prep collision rejected");Assert(f.PhoneSnapshot(f.Day.Date).revision==before.revision,"entire change rolled back");}));
   check("plan edit: score changes preserve manual positions and the next meal resumes future adjustment",()=>With(dir,"resume",f=>{var original=f.PhoneSnapshot(f.Day.Date);var second=Meal(original,"b6");var manual=MovePlan(f,second,second.start+3);Assert(f.Day.ManualPlan&&Meal(manual,"b6").start==second.start+3,"manual position retained");var score=Cmd(f,"score",60,1,1);score.score=5;var scored=f.PhoneApply(score);Same(Meal(manual,"b6"),Meal(scored,"b6"));Assert(f.Day.ManualPlan,"score is not a timing change");var first=Meal(scored,"b1");var eat=Cmd(f,"copy",first.start+6,3,1);eat.sourceId=first.id;var after=f.PhoneApply(eat);Assert(!f.Day.ManualPlan&&Meal(after,"b6").start!=Meal(manual,"b6").start,"future automation resumed");Same(first,Meal(after,"b1"));Assert(Meal(after,"b6").start>=after.actual.Single(x=>x.mealId=="b1").start+18,"automatic meal gap respected");}));
   check("plan edit: undo restores both the upper group and its automatic scheduling mode",()=>With(dir,"undo",f=>{var original=f.PhoneSnapshot(f.Day.Date);MovePlan(f,Meal(original,"b6"),Meal(original,"b6").start+3);var undo=Cmd(f,"undo",0);undo.sourceId=f.Data.RemoteReceipts.Last().id;var after=f.PhoneApply(undo);Assert(!f.Day.ManualPlan,"automatic mode restored");foreach(var b in original.planned)Same(b,after.planned.Single(x=>x.id==b.id));}));
   check("plan edit: moving current meal before past plans never unfreezes those plans",()=>With(dir,"reorder",f=>{var before=EatSecond(f);var moved=MovePlan(f,Meal(before,"b6"),58);var actual=moved.actual.Single(x=>x.mealId=="b6");var edit=Cmd(f,"move",72,1,1);edit.id=actual.id;var after=f.PhoneApply(edit);foreach(var b in before.planned.Where(x=>x.start<Meal(before,"b6").start&&x.name!="2끼니 준비"))Same(b,after.planned.Single(x=>x.id==b.id));Same(Meal(moved,"b6"),Meal(after,"b6"));}));
  }
 }
}
